# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  it "applies a create and an update of the same entry delivered together in one batch" do
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    snapshot = lambda do |id:, version:, generation: 1, position: version|
      entry = TimekeepingSnapshots.entry(id:, company_id: company.id, version:, project_id: project.id, user_id: user.id)
      TimekeepingSnapshots.item(entry, generation:, outbox_position: position)
    end

    # A paused relay sends every unsent snapshot at once, so one batch can hold
    # several versions of one entry. The batch must not fail because of that.
    # "It upserts by entry `id` and applies a snapshot only when its `version` is higher than the row's."
    result = described_class.call(
      batch: TimekeepingSnapshots.batch(snapshot.call(id: 71_001, version: 1), snapshot.call(id: 71_001, version: 2)),
      idempotency_key: SecureRandom.uuid
    )

    expect(result.status).to eq(200)
    expect(result.body.to_h.deep_stringify_keys).to eq("applied" => 2, "ignored" => 0)
    stored = ActiveRecord::Base.connection.select_one("SELECT version, note FROM timesheet_entries WHERE id = 71001")
    expect(stored).to include("version" => 2, "note" => "v2")
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "writes none of the valid snapshots that come before a stale one in the same batch" do
    TimekeepingOwnership.ensure_initial!
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: nil)
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    snapshot = lambda do |id:, version:, generation:, position:|
      entry = TimekeepingSnapshots.entry(id:, company_id: company.id, version:, project_id: project.id, user_id: user.id)
      TimekeepingSnapshots.item(entry, generation:, outbox_position: position)
    end

    # A batch holding any refused snapshot answers stale_generation and applies
    # nothing, so a write loop that stops at the first refusal must not leave
    # the earlier items behind.
    result = described_class.call(
      batch: TimekeepingSnapshots.batch(
        snapshot.call(id: 72_001, version: 1, generation: 2, position: 1),
        snapshot.call(id: 72_002, version: 1, generation: 2, position: 2),
        snapshot.call(id: 72_003, version: 1, generation: 1, position: 3)
      ),
      idempotency_key: SecureRandom.uuid
    )

    expect(result.status).to eq(409)
    expect(result.body.to_h.deep_stringify_keys).to eq("reason" => "stale_generation")
    count = ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM timesheet_entries WHERE id IN (72001, 72002, 72003)")
    expect(count.to_i).to eq(0)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a higher-version snapshot that names another company for an existing entry id" do
    TimekeepingOwnership.ensure_initial!
    company_a = create(:company)
    company_b = create(:company)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    user = create(:user)
    snapshot = lambda do |company:, project:, version:|
      entry = TimekeepingSnapshots.entry(id: 73_001, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1))
    end
    described_class.call(batch: snapshot.call(company: company_a, project: project_a, version: 1), idempotency_key: SecureRandom.uuid)
    read_row = -> { ActiveRecord::Base.connection.select_one("SELECT * FROM timesheet_entries WHERE id = 73001") }
    before = read_row.call
    expect(before).to include("version" => 1, "company_id" => company_a.id)

    # "A snapshot whose `company_id` differs from the row's is refused."
    # The version is higher, so only the company check can refuse it.
    result = described_class.call(batch: snapshot.call(company: company_b, project: project_b, version: 5), idempotency_key: SecureRandom.uuid)

    expect(result.status).to eq(409)
    expect(result.body.to_h.deep_stringify_keys).to eq("reason" => "stale_generation")
    expect(result.body.to_h.to_s).not_to include(company_a.id.to_s)
    expect(read_row.call).to eq(before)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a new entry whose project belongs to another company so it never reaches that company's reports" do
    TimekeepingOwnership.ensure_initial!
    company_a = create(:company)
    company_b = create(:company)
    project_b = create(:project, client: create(:client, company: company_b))
    user = create(:user)
    entry = TimekeepingSnapshots.entry(id: 74_001, company_id: company_a.id, version: 1, project_id: project_b.id,
                                       user_id: user.id, note: "company A private note")

    # Company#timesheet_entries joins through clients and projects, so a row
    # filed under company B's project would show in company B's reports.
    result = described_class.call(
      batch: TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1)),
      idempotency_key: SecureRandom.uuid
    )

    expect(result.status).to eq(422)
    expect(result.body.to_h.deep_stringify_keys).to eq("reason" => "invalid_snapshot")
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM timesheet_entries WHERE id = 74001").to_i).to eq(0)
    expect(company_b.timesheet_entries.where(id: 74_001)).to be_empty
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "refuses a previous-generation snapshot delivered after the flip even below the final outbox position" do
    TimekeepingOwnership.ensure_initial!
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "freeze", final_outbox_position: 10)
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    snapshot = lambda do |version:, generation:, position:|
      entry = TimekeepingSnapshots.entry(id: 75_001, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation:, outbox_position: position))
    end

    # "During a handoff, between closing admission and the ownership flip, it also accepts the outgoing owner's
    # previous-generation snapshots, but only up to the final outbox position captured when that owner was frozen.
    # The flip removes that permission."
    at_final = described_class.call(batch: snapshot.call(version: 1, generation: 1, position: 10), idempotency_key: SecureRandom.uuid)
    past_final = described_class.call(batch: snapshot.call(version: 2, generation: 1, position: 11), idempotency_key: SecureRandom.uuid)
    expect(at_final.status).to eq(200)
    expect(past_final.status).to eq(409)

    # The flip clears handoff_step; P is left set on purpose, so the refusal
    # must come from the flip and not from a cleared position.
    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil)
    late = described_class.call(batch: snapshot.call(version: 5, generation: 1, position: 5), idempotency_key: SecureRandom.uuid)

    expect(late.status).to eq(409)
    expect(late.body.to_h.deep_stringify_keys).to eq("reason" => "stale_generation")
    expect(ActiveRecord::Base.connection.select_one("SELECT version FROM timesheet_entries WHERE id = 75001")).to include("version" => 1)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "replays the first answer to a delivery retried after the flip and refuses a changed batch under the same key" do
    TimekeepingOwnership.ensure_initial!
    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "freeze", final_outbox_position: 10)
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    snapshot = lambda do |version:|
      entry = TimekeepingSnapshots.entry(id: 76_001, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1))
    end
    key = SecureRandom.uuid

    first = described_class.call(batch: snapshot.call(version: 1), idempotency_key: key)
    expect(first.status).to eq(200)
    expect(first.body.to_h.deep_stringify_keys).to eq("applied" => 1, "ignored" => 0)

    # The relay lost the 200 and retries after the flip. The receipt is read
    # before the generation check, so it gets its first answer, not 409.
    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil, final_outbox_position: nil)
    replay = described_class.call(batch: snapshot.call(version: 1), idempotency_key: key)
    expect([replay.status, replay.body.to_h.deep_stringify_keys]).to eq([200, { "applied" => 1, "ignored" => 0 }])

    TimekeepingOwnership.current.update!(generation: 2, owner: "timekeeping")
    reused = described_class.call(batch: snapshot.call(version: 2), idempotency_key: key)
    expect([reused.status, reused.body.to_h.deep_stringify_keys]).to eq([422, { "reason" => "idempotency_key_reused" }])
    expect(ActiveRecord::Base.connection.select_one("SELECT version FROM timesheet_entries WHERE id = 76001")).to include("version" => 1)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "keeps a tombstoned entry discarded when an older live snapshot arrives late" do
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    snapshot = lambda do |version:, discarded_at: nil|
      entry = TimekeepingSnapshots.entry(id: 77_001, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id, discarded_at:)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1))
    end

    # "A discard arrives as a snapshot with `discarded_at` set (a 'tombstone'), never as a row delete."
    described_class.call(batch: snapshot.call(version: 3, discarded_at: "2026-03-03T10:00:00Z"), idempotency_key: SecureRandom.uuid)
    late = described_class.call(batch: snapshot.call(version: 2), idempotency_key: SecureRandom.uuid)

    expect(late.status).to eq(200)
    expect(late.body.to_h.deep_stringify_keys).to eq("applied" => 0, "ignored" => 1)
    stored = ActiveRecord::Base.connection.select_one("SELECT version, discarded_at FROM timesheet_entries WHERE id = 77001")
    expect(stored).not_to be_nil
    expect(stored["version"]).to eq(3)
    expect(stored["discarded_at"]).not_to be_nil
  end
end
